"use strict";
// Disposable PostgreSQL 17 recovery acceptance. This test never targets
// Supabase. It requires HH_RECOVERY_POSTGRES_CI=1 and a CI-only Postgres service.
// The encrypted backup is generated by S19, independently read in a separate
// process, and restored into a fresh PostgreSQL schema with real FK and JSONB.
const test=require("node:test");
const assert=require("node:assert/strict");
const fs=require("node:fs");
const path=require("node:path");
const os=require("node:os");
const crypto=require("node:crypto");
const {spawnSync}=require("node:child_process");
const {storeBackup}=require("../scripts/s19-cloud-migration.cjs");
const normalizer=require("../cloud-state-normalizer-v1.8.3.js");
const enabled=process.env.HH_RECOVERY_POSTGRES_CI==="1";
const secret="synthetic-postgres-restore-passphrase-2026";
const uid="123e4567-e89b-42d3-a456-426614174000";
const quote=s=>"'"+String(s).replaceAll("'","''")+"'";
function exec(bin,args,input,extraEnv={}) {
  const result=spawnSync(bin,args,{input,encoding:"utf8",timeout:45000,
    env:{...process.env,...extraEnv}});
  assert.equal(result.error,undefined, result.error?.message);
  assert.equal(result.status,0,[bin,result.stderr,result.stdout].join("\n").slice(0,6000));
  return result.stdout.trim();
}
const pg=sql=>exec("psql",["-X","-A","-t","-q","-v","ON_ERROR_STOP=1"],sql);
function farm(){
  const app_state={
    operation:{name:"Disposable Postgres Recovery Farm"},
    animals:[
      {id:"dog-db",species:"dog",name:"Scout",breed:"Great Pyrenees"},
      {id:"rabbit-db",species:"rabbit",name:"Clover",breed:"Holland Lop"}
    ],
    litters:[{id:"litter-db",species:"rabbit",damId:"rabbit-db"}],
    tasks:[{id:"task-db",animalId:"dog-db",category:"Canine reproduction"}],
    settings:{aiEnabled:false,notifications:true}
  };
  const rows=normalizer.mapLegacySnapshot(app_state).records.map(r=>({...r,record_version:1,deleted_at:null}));
  const tombstone={kind:"array_item",key:"animals",value:{id:"removed-rabbit",species:"rabbit"}};
  rows.push({namespace:"legacy-state",record_id:"historical-tombstone",
    payload:tombstone,payload_checksum:normalizer.checksumValue(tombstone),
    record_version:3,deleted_at:"2026-10-20T12:00:00.000Z"});
  return {userId:uid,legacy:{app_state,updated_at:"2026-10-29T10:00:00.000Z"},
    manifest:{cutover_stage:"dual_write",sync_generation:7},rows,
    enabled:true,cohort:"internal_test"};
}
test("2.0.2 encrypted recovery restores into independently provisioned PostgreSQL 17", {skip:!enabled},()=>{
  const dir=fs.mkdtempSync(path.join(os.tmpdir(),"hh-postgres-restore-"));
  try{
    const input=farm();
    const archived=storeBackup(input,dir,secret);
    const destination=path.join(dir,"readback.json");
    const stdout=exec(process.execPath,[
      path.resolve(__dirname,"../scripts/s19-independent-backup-verify.cjs"),
      "--backup",archived.file,"--expect-user",uid,
      "--expect-sha256",archived.checksum,"--output",destination
    ],undefined,{S19_BACKUP_PASSPHRASE:secret});
    assert.equal(JSON.parse(stdout).ok,true);
    const restored=JSON.parse(fs.readFileSync(destination,"utf8"));
    assert.deepEqual(restored,input);
    const plainDigest=crypto.createHash("sha256")
      .update(fs.readFileSync(destination)).digest("hex");
    assert.equal(plainDigest,archived.checksum);
    const sqlRows=quote(JSON.stringify(restored.rows));
    const sqlState=quote(JSON.stringify(restored.legacy.app_state));
    pg(`drop schema if exists hh_s19_recovery_ci cascade;
create schema hh_s19_recovery_ci;
create table hh_s19_recovery_ci.auth_users (id uuid primary key);
create table hh_s19_recovery_ci.legacy (
  user_id uuid primary key references hh_s19_recovery_ci.auth_users(id) on delete cascade,
  app_state jsonb not null, updated_at timestamptz not null
);
create table hh_s19_recovery_ci.records (
  user_id uuid not null references hh_s19_recovery_ci.auth_users(id) on delete cascade,
  namespace text not null, record_id text not null,
  payload jsonb not null, payload_checksum text not null,
  record_version bigint not null, deleted_at timestamptz,
  primary key(user_id,namespace,record_id)
);
create table hh_s19_recovery_ci.manifest (
  user_id uuid primary key references hh_s19_recovery_ci.auth_users(id) on delete cascade,
  cutover_stage text not null, sync_generation bigint not null
);
begin transaction isolation level serializable;
insert into hh_s19_recovery_ci.auth_users(id) values ('${uid}');
insert into hh_s19_recovery_ci.legacy(user_id,app_state,updated_at)
 values ('${uid}',${sqlState}::jsonb,'${restored.legacy.updated_at}'::timestamptz);
insert into hh_s19_recovery_ci.manifest(user_id,cutover_stage,sync_generation)
 values ('${uid}','legacy',${restored.manifest.sync_generation});
insert into hh_s19_recovery_ci.records(user_id,namespace,record_id,payload,payload_checksum,record_version,deleted_at)
select '${uid}'::uuid,namespace,record_id,payload,payload_checksum,record_version,deleted_at
from jsonb_to_recordset(${sqlRows}::jsonb)
as x(namespace text,record_id text,payload jsonb,payload_checksum text,
     record_version bigint,deleted_at timestamptz);
commit;`);
    const readback=JSON.parse(pg(`select jsonb_build_object(
      'app_state',(select app_state from hh_s19_recovery_ci.legacy where user_id='${uid}'),
      'stage',(select cutover_stage from hh_s19_recovery_ci.manifest where user_id='${uid}'),
      'rows',(select coalesce(jsonb_agg(jsonb_build_object(
        'namespace',namespace,'record_id',record_id,'payload',payload,
        'payload_checksum',payload_checksum,'record_version',record_version,
        'deleted',deleted_at is not null) order by record_id),'[]'::jsonb)
        from hh_s19_recovery_ci.records where user_id='${uid}')
    )::text;`));
    assert.deepEqual(readback.app_state,restored.legacy.app_state);
    assert.equal(readback.stage,"legacy");
    assert.equal(readback.rows.length,restored.rows.length);
    assert.equal(readback.rows.filter(r=>r.deleted).length,1);
    const byId=new Map(restored.rows.map(r=>[r.record_id,r]));
    for(const row of readback.rows){
      const expected=byId.get(row.record_id);
      assert.ok(expected,row.record_id);
      assert.equal(row.namespace,expected.namespace);
      assert.deepEqual(row.payload,expected.payload);
      assert.equal(row.payload_checksum,expected.payload_checksum);
      assert.equal(Number(row.record_version),expected.record_version);
      assert.equal(row.deleted,Boolean(expected.deleted_at));
    }
    const rebuilt=normalizer.reassembleAuthoritativeSnapshotWithMetadata(
      readback.rows.map(row=>({...row,deleted_at:row.deleted?"2026-10-20T12:00:00.000Z":null})));
    assert.equal(rebuilt.checkpointStale,false);
    assert.deepEqual(JSON.parse(JSON.stringify(rebuilt.snapshot)), restored.legacy.app_state);
    pg("drop schema hh_s19_recovery_ci cascade;");
  } finally {fs.rmSync(dir,{force:true,recursive:true});}
});
